/**
 * The Opinions page's Madhubani-style art, as SVG markup. Generated, then checked in. The drawings are original,
 * built from simple shapes in the Madhubani manner: every shape has a double outline (ink with a paper hairline)
 * and a flat or patterned fill (hatching, dots, scales, zigzags), with flowers, leaves, fish, lotuses and birds
 * as fillers. Colours come from the palette tokens --ink, --paper, --link, --mb-accent, --mb-green and --mb-red
 * (see styles/stack.css), so the art follows the chosen paper.
 *
 * motifDefs holds the fill patterns, one 200 x 200 <symbol id="mb-…"> per motif, and the filler panels.
 * painting is one long vertical strip, like a sleeve tattoo: the motifs stacked with a filler panel between each,
 * sawtooth borders down both edges, drawn twice so it can loop. frieze is the same painting laid left to right
 * for phones.
 */

/** Every motif with a symbol. */
export type MotifId =
  | "chess"
  | "kolkata"
  | "mocha"
  | "dragon"
  | "wizard"
  | "tennis"
  | "orb"
  | "gate"
  | "pickleball"
  | "padel"
  | "sword"
  | "five"
  | "diary"
  | "ring"
  | "locket"
  | "cup"
  | "diadem"
  | "nagini"
  | "gsword"
  | "magic"
  | "hallows"
  | "cola";

